content:
:root {
  --primary-color: #2563eb;
  --primary-hover: #1d4ed8;
  --bg-color: #f8fafc;
  --card-bg: #ffffff;
  --text-color: #1e293b;
  --text-muted: #64748b;
  --border-color: #e2e8f0;
  --shadow: 0 4px 6px -1px rgb(0 0 0 / 0.1), 0 2px 4px -2px rgb(0 0 0 / 0.1);
  --radius: 12px;
}

html {
  box-sizing: border-box;
  scroll-behavior: smooth;
}

* {
  box-sizing: inherit;
  margin: 0;
  padding: 0;
}

body {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  background-color: var(--bg-color);
  color: var(--text-color);
  line-height: 1.5;
  padding: 12px;
}

@media (min-width: 600px) {
  body {
    padding: 20px;
  }
}

.app-container {
  max-width: 1200px;
  margin: 0 auto;
  padding: 10px;
}

@media (min-width: 600px) {
  .app-container {
    padding: 20px;
  }
}

.header {
  text-align: center;
  margin-bottom: 32px;
}

.header h1 {
  font-size: 2.25rem;
  font-weight: 700;
  color: var(--primary-color);
  margin-bottom: 8px;
}

.header p {
  color: var(--text-muted);
  font-size: 1rem;
}

.simulator-layout {
  display: grid;
  grid-template-columns: 1fr;
  gap: 24px;
}

@media (min-width: 900px) {
  .simulator-layout {
    grid-template-columns: 380px 1fr;
  }
}

.control-panel {
  background-color: var(--card-bg);
  padding: 24px;
  border-radius: var(--radius);
  box-shadow: var(--shadow);
  display: flex;
  flex-direction: column;
  gap: 20px;
  height: fit-content;
}

.input-group {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.input-group label {
  font-weight: 600;
  font-size: 0.9rem;
  color: var(--text-color);
}

.input-group input,
.input-group select {
  width: 100%;
  padding: 10px 12px;
  border: 1px solid var(--border-color);
  border-radius: 8px;
  font-size: 1rem;
  outline: none;
  transition: border-color 0.2s, box-shadow 0.2s;
}

.input-group input:focus,
.input-group select:focus {
  border-color: var(--primary-color);
  box-shadow: 0 0 0 3px rgba(37, 99, 235, 0.15);
  outline: none;
}

.result-section {
  display: flex;
  flex-direction: column;
  gap: 24px;
}

.summary-cards {
  display: grid;
  grid-template-columns: 1fr;
  gap: 16px;
}

@media (min-width: 600px) {
  .summary-cards {
    grid-template-columns: repeat(2, 1fr);
  }
}

.card {
  background-color: var(--card-bg);
  padding: 20px;
  border-radius: var(--radius);
  box-shadow: var(--shadow);
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.card h3 {
  font-size: 0.9rem;
  color: var(--text-muted);
  font-weight: 500;
}

.card .card-value {
  font-size: 1.75rem;
  font-weight: 700;
  color: var(--primary-color);
}

.chart-section {
  background-color: var(--card-bg);
  padding: 24px;
  border-radius: var(--radius);
  box-shadow: var(--shadow);
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.chart-section h3 {
  font-size: 1.1rem;
  font-weight: 600;
  color: var(--text-color);
}

.btn {
  background-color: var(--primary-color);
  color: white;
  border: none;
  border-radius: 8px;
  padding: 12px 20px;
  font-size: 1rem;
  font-weight: 600;
  cursor: pointer;
  transition: background-color 0.2s, transform 0.1s, box-shadow 0.2s;
  width: 100%;
  text-align: center;
}

.btn:hover {
  background-color: var(--primary-hover);
}

.btn:focus-visible {
  outline: 2px solid var(--primary-color);
  outline-offset: 2px;
  box-shadow: 0 0 0 3px rgba(37, 99, 235, 0.2);
}

.btn:active {
  transform: scale(0.98);
}

/**
 * 住宅ローンシミュレーションの入力パラメータ
 */
export interface SimulationParams {
  /** 借入金額 (円) */
  readonly loanAmount: number;
  /** 金利 (年利 %) */
  readonly interestRate: number;
  /** 返済期間 (年) */
  readonly loanYears: number;
  /** ボーナス払い併用時の年間ボーナス返済額 (円) - 将来拡張用 */
  readonly bonusAmount?: number;
  /** 返済方式 ('annuity' = 元利均等, 'principal' = 元金均等) - 将来拡張用 */
  readonly repaymentType?: 'annuity' | 'principal';
}

/**
 * 年ごとの返済残高・内訳データ
 */
export interface YearlyBalance {
  /** 経過年数 */
  readonly year: number;
  /** 年末時点の残高 (円) */
  readonly remainingBalance: number;
  /** 累計支払額 (円) */
  readonly totalPaid: number;
  /** 元本返済額 (円) */
  readonly principalPaid: number;
  /** 利息支払額 (円) */
  readonly interestPaid: number;
  /** その年のボーナス返済額 (円) - 将来拡張用 */
  readonly yearlyBonusPaid?: number;
}

import { useState, useMemo } from 'react';
import { 
  BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer 
} from 'recharts';
import { SimulationParams, YearlyBalance } from './types';
import './index.css';

export default function App() {
  const [params, setParams] = useState<SimulationParams>({
    loanAmount: 30000000,
    interestRate: 1.5,
    loanYears: 35,
  });

  const [error, setError] = useState<string | null>(null);

  const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const { name, value } = e.target;
    const numValue = Number(value);

    if (name === 'loanAmount' && numValue <= 0) {
      setError('借入金額は0より大きい値を入力してください。');
    } else if (name === 'interestRate' && (numValue < 0 || numValue > 20)) {
      setError('金利は0%から20%の間で入力してください。');
    } else if (name === 'loanYears' && (numValue < 1 || numValue > 50)) {
      setError('返済期間は1年から50年の間で入力してください。');
    } else {
      setError(null);
    }

    setParams(prev => ({
      ...prev,
      [name]: numValue,
    }));
  };

  const { monthlyPayment, totalPayment, totalInterest, yearlyBalances } = useMemo(() => {
    const principal = params.loanAmount;
    const monthlyRate = params.interestRate / 100 / 12;
    const totalMonths = params.loanYears * 12;

    let monthly = 0;
    if (monthlyRate === 0) {
      monthly = principal / totalMonths;
    } else {
      monthly = 
        (principal * monthlyRate * Math.pow(1 + monthlyRate, totalMonths)) /
        (Math.pow(1 + monthlyRate, totalMonths) - 1);
    }

    const totalPay = monthly * totalMonths;
    const totalInt = totalPay - principal;

    const balances: YearlyBalance[] = [];
    let currentBalance = principal;
    let accumulatedPaid = 0;
    let accumulatedPrincipal = 0;
    let accumulatedInterest = 0;

    for (let year = 1; year <= params.loanYears; year++) {
      let yearlyPrincipal = 0;
      let yearlyInterest = 0;

      for (let m = 0; m < 12; m++) {
        if (currentBalance <= 0) break;
        const interestForMonth = currentBalance * monthlyRate;
        const principalForMonth = monthly - interestForMonth;

        yearlyInterest += interestForMonth;
        yearlyPrincipal += principalForMonth;
        currentBalance -= principalForMonth;
        if (currentBalance < 0) currentBalance = 0;
      }

      accumulatedPrincipal += yearlyPrincipal;
      accumulatedInterest += yearlyInterest;
      accumulatedPaid += (yearlyPrincipal + yearlyInterest);

      balances.push({
        year,
        remainingBalance: Math.round(currentBalance),
        totalPaid: Math.round(accumulatedPaid),
        principalPaid: Math.round(accumulatedPrincipal),
        interestPaid: Math.round(accumulatedInterest),
      });
    }

    return {
      monthlyPayment: Math.round(monthly),
      totalPayment: Math.round(totalPay),
      totalInterest: Math.round(totalInt),
      yearlyBalances: balances,
    };
  }, [params]);

  const formatCurrency = (val: number) => {
    return val.toLocaleString('ja-JP') + '円';
  };

  return (
    <div className="app-container">
      <header className="header">
        <h1>住宅ローンシミュレーター</h1>
        <p>借入額・金利・返済期間を入力して、毎月の返済額や総返済額、推移グラフを確認できます。</p>
      </header>

      <div className="simulator-layout">
        <div className="control-panel">
          {error && (
            <div style={{ color: '#ef4444', fontSize: '0.875rem', fontWeight: 600, marginBottom: '8px' }}>
              {error}
            </div>
          )}
          <div className="input-group">
            <label htmlFor="loanAmount">借入金額 (円)</label>
            <input
              type="number"
              id="loanAmount"
              name="loanAmount"
              value={params.loanAmount}
              onChange={handleChange}
              step={1000000}
              min={0}
            />
          </div>

          <div className="input-group">
            <label htmlFor="interestRate">金利 (年利 %)</label>
            <input
              type="number"
              id="interestRate"
              name="interestRate"
              value={params.interestRate}
              onChange={handleChange}
              step={0.1}
              min={0}
              max={20}
            />
          </div>

          <div className="input-group">
            <label htmlFor="loanYears">返済期間 (年)</label>
            <input
              type="number"
              id="loanYears"
              name="loanYears"
              value={params.loanYears}
              onChange={handleChange}
              step={1}
              min={1}
              max={50}
            />
          </div>
        </div>

        <div className="result-section">
          <div className="summary-cards">
            <div className="card">
              <h3>毎月の返済額</h3>
              <div className="card-value">{formatCurrency(monthlyPayment)}</div>
            </div>
            <div className="card">
              <h3>総返済額</h3>
              <div className="card-value">{formatCurrency(totalPayment)}</div>
            </div>
            <div className="card">
              <h3>総利息額</h3>
              <div className="card-value">{formatCurrency(totalInterest)}</div>
            </div>
            <div className="card">
              <h3>借入期間</h3>
              <div className="card-value">{params.loanYears}年</div>
            </div>
          </div>

          <div className="chart-section">
            <h3>年ごとの返済推移（元本・利息）</h3>
            <div style={{ width: '100%', height: 350 }}>
              <ResponsiveContainer>
                <BarChart data={yearlyBalances}>
                  <CartesianGrid strokeDasharray="3 3" />
                  <XAxis dataKey="year" tickFormatter={(val) => `${val}年`} />
                  <YAxis tickFormatter={(val) => `${val / 10000}万`} />
                  <Tooltip formatter={(value: any) => formatCurrency(Number(value))} />
                  <Legend />
                  <Bar dataKey="principalPaid" name="元本返済額" stackId="a" fill="#2563eb" />
                  <Bar dataKey="interestPaid" name="利息支払額" stackId="a" fill="#93c5fd" />
                </BarChart>
              </ResponsiveContainer>
            </div>
          </div>

          <div className="chart-section">
            <h3>年ごとの返済予定表</h3>
            <div style={{ width: '100%', maxHeight: 300, overflowY: 'auto' }}>
              <table style={{ width: '100%', borderCollapse: 'collapse', fontSize: '0.9rem', textAlign: 'right' }}>
                <thead>
                  <tr style={{ borderBottom: '2px solid var(--border-color)', color: 'var(--text-muted)' }}>
                    <th style={{ padding: '8px', textAlign: 'center' }}>年</th>
                    <th style={{ padding: '8px' }}>年間元本返済</th>
                    <th style={{ padding: '8px' }}>年間利息支払</th>
                    <th style={{ padding: '8px' }}>年末残高</th>
                  </tr>
                </thead>
                <tbody>
                  {yearlyBalances.map((item, index) => {
                    const prevPrincipal = index > 0 ? yearlyBalances[index - 1].principalPaid : 0;
                    const prevInterest = index > 0 ? yearlyBalances[index - 1].interestPaid : 0;
                    const yearlyPrincipal = item.principalPaid - prevPrincipal;
                    const yearlyInterest = item.interestPaid - prevInterest;

                    return (
                      <tr key={item.year} style={{ borderBottom: '1px solid var(--border-color)' }}>
                        <td style={{ padding: '8px', textAlign: 'center' }}>{item.year}年目</td>
                        <td style={{ padding: '8px' }}>{formatCurrency(yearlyPrincipal)}</td>
                        <td style={{ padding: '8px' }}>{formatCurrency(yearlyInterest)}</td>
                        <td style={{ padding: '8px' }}>{formatCurrency(item.remainingBalance)}</td>
                      </tr>
                    );
                  })}
                </tbody>
              </table>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}
